def compute(vars):
    total = vars["v1"] + vars["v2"]
    count = 2
    average = total / count

    return {
        "value": average,
        "trace": {
            "values": [vars["v1"], vars["v2"]],
            "total": total,
            "count": count,
            "average": average,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": None
            }
        }
    }
